import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long m = Long.parseLong(next());
        long[][] costs = new long[(int) m][2];
        for (int i = 0; i < costs.length; i++) {
            for (int j = 0; j < costs[i].length; j++) {
                costs[i][j] = Long.parseLong(next());
            }
        }

        int count = (int) m;
        long[] diff = new long[count];
        long sumB = 0;
        for (int i = 0; i < count; i++) {
            diff[i] = costs[i][0] - costs[i][1];
            sumB += costs[i][1];
        }
        Arrays.sort(diff);
        long total = sumB;
        for (int i = 0; i < count / 2; i++) total += diff[i];
        System.out.println(total);
    }
}
